import java.util.Locale;

public class Main {
    sealed interface Node permits Text, Num, Pair, ExtensionNode {}
    record Text(String value) implements Node {}
    record Num(int value) implements Node {}
    record Pair(Node left, Node right) implements Node {}

    non-sealed interface ExtensionNode extends Node {}
    static final class UnknownNode implements ExtensionNode {
        private final Object raw;
        UnknownNode(Object raw) { this.raw = raw; }
        Object raw() { return raw; }
    }

    // instanceof 类型模式 + flow scoping
    static String classify(Object obj) {
        if (obj == null) return "null";
        if (obj instanceof String s && s.length() >= 4) {
            return "long string:" + s.toUpperCase(Locale.ROOT);
        }
        if (obj instanceof String s) return "short string:" + s;
        if (obj instanceof Integer i) return "int+1:" + (i + 1);
        return "other:" + obj.getClass().getSimpleName();
    }

    // 否定匹配提前 return 后，模式变量在后续路径可见
    static int lengthIfString(Object obj) {
        if (!(obj instanceof String s)) return -1;
        return s.length();
    }

    // sealed + non-sealed 的分派现实：non-sealed 分支需要兜底
    static int score(Node node) {
        if (node instanceof Text t) return t.value().length();
        if (node instanceof Num n) return n.value();
        if (node instanceof Pair p) return score(p.left()) + score(p.right());
        if (node instanceof UnknownNode u) return u.raw().toString().length();
        throw new IllegalArgumentException("unsupported: " + node.getClass().getName());
    }

    public static void main(String[] args) {
        System.out.println(classify("codex"));   // long string:CODEX
        System.out.println(classify("go"));      // short string:go
        System.out.println(classify(41));         // int+1:42
        System.out.println(classify(null));       // null

        Node tree = new Pair(new Text("java"), new Pair(new Num(3), new UnknownNode("x")));
        System.out.println("score: " + score(tree)); // 8

        assert classify("codex").equals("long string:CODEX");
        assert classify("go").equals("short string:go");
        assert classify(41).equals("int+1:42");
        assert classify(null).equals("null");
        assert lengthIfString("scope") == 5;
        assert lengthIfString(42) == -1;
        assert score(tree) == 8;
    }
}
